#include <bits/stdc++.h>
using namespace std;
// Exact two-label signed X6 prefix-trie DP. Input trie generated by
// EC49FIO MAKE_INPUT_EC49FIO.py (original seven raw cache keys).
// Representative masks generated by VERIFY_EC49FIX.py.
struct Node{int parent;uint32_t support,terminal;};
int main(int argc,char**argv){
 if(argc!=3){cerr<<"Usage: verify_pair TRIE B3_REP_MASKS\n";return 2;}
 ifstream f(argv[1]);vector<Node> trie;int p;unsigned s,t;
 while(f>>p>>s>>t)trie.push_back({p,s,t});
 assert(trie.size()==42735);
 ifstream r(argv[2]);uint32_t q;int g=0;
 while(r>>q){
  for(int a=0;a<24;a++)for(int b=a+1;b<24;b++){
   vector<array<uint8_t,4>> dp(trie.size());
   for(int u=0;u<(int)trie.size();u++){
    auto &d=dp[u];d={99,99,99,99};d[0]=0;
    if(trie[u].terminal&(1u<<a))d[1]=0;
    if(trie[u].terminal&(1u<<b))d[2]=0;
   }
   for(int u=(int)trie.size()-1;u>0;u--){
    auto &x=dp[trie[u].parent];auto &y=dp[u];
    int e=((trie[u].support & ~q)==0)?1:0;
    int x1=x[1],x2=x[2],x3=x[3];
    x[3]=min({x3,(int)y[3]+e,x1+(int)y[2]+e,x2+(int)y[1]+e});
    x[1]=min(x1,(int)y[1]+e);
    x[2]=min(x2,(int)y[2]+e);
   }
   cout<<g<<' '<<a<<' '<<b<<' '<<(int)dp[0][3]<<'\n';
  }
  cerr<<"GROUP "<<g<<" complete\n";g++;
 }
 assert(g==10);
}
